param([string]$RemoteHost='h200-codex',[string]$RemotePath='/home/hera/pid_reliability_benchmark/outputs/telemetry/efficiency_repeats_v2.jsonl',[string]$LocalPath='outputs/telemetry/efficiency_repeats_v2.jsonl')
$ErrorActionPreference='Stop';$ssh=Join-Path $env:WINDIR 'System32/OpenSSH/ssh.exe';$si=New-Object Diagnostics.ProcessStartInfo;$si.FileName=$ssh;$si.Arguments="-o BatchMode=yes $RemoteHost `"base64 -w0 $RemotePath`"";$si.UseShellExecute=$false;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true;$p=New-Object Diagnostics.Process;$p.StartInfo=$si;[void]$p.Start();$enc=$p.StandardOutput.ReadToEnd();$err=$p.StandardError.ReadToEnd();$p.WaitForExit();if($p.ExitCode -ne 0){throw "pull failed: $err"};$bytes=[Convert]::FromBase64String(($enc -replace '\s',''));$dir=Split-Path -Parent (Join-Path (Get-Location) $LocalPath);[IO.Directory]::CreateDirectory($dir)|Out-Null;[IO.File]::WriteAllBytes((Join-Path (Get-Location) $LocalPath),$bytes);Write-Output("pulled bytes={0}" -f $bytes.Length)
